144. impl Inner {
145.     ///
146.     /// # Description
147.     ///
148.     /// Allocates a frame.
149.     ///
150.     /// # Returns
151.     ///
152.     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
153.     /// returned instead.
154.     ///
155.     #[verus_spec(result =>
156.         requires
157.             old(self).inv(),
158.         ensures
159.             self.inv(),
160.             match result {
161.                 Ok(frame) => {
162.                     &&& frame.inv()
163.                     &&& old(self)@.free_frames.contains(frame@)
164.                     &&& self@ == old(self)@.spec_alloc(frame@)
165.                 },
166.                 Err(_) => {
167.                     &&& self@ == old(self)@
168.                     &&& old(self)@.free_frames.is_empty()
169.                 }
170.             },
171.     )]
172.     fn alloc(&mut self) -> Result<FrameAddress, Error> {
173.         let index: usize = match self.bitmap.alloc() {
174.             Ok(index) => index,
175.             Err(error) => {
176.                 proof! {
177.                     // bitmap unchanged
178.                     assert(self.bitmap@.set_bits =~= old(self).bitmap@.set_bits);
179.                     assert(self.bitmap@.chunks =~= old(self).bitmap@.chunks);
180. 
181.                     // self@ == old(self)@ (view unchanged because bitmap unchanged)
182.                     assert forall|addr: int|
183.                         self@.allocated_frames.contains(addr)
184.                         <==> old(self)@.allocated_frames.contains(addr)
185.                     by {
186.                         if self@.allocated_frames.contains(addr) {
187.                             let i = choose|i: int|
188.                                 #[trigger] self.bitmap@.set_bits.contains(i)
189.                                 && addr == frame_addr_of(i);
190.                             assert(old(self).bitmap@.set_bits.contains(i));
191.                         }
192.                         if old(self)@.allocated_frames.contains(addr) {
193.                             let i = choose|i: int|
194.                                 #[trigger] old(self).bitmap@.set_bits.contains(i)
195.                                 && addr == frame_addr_of(i);
196.                             assert(self.bitmap@.set_bits.contains(i));
197.                         }
198.                     }
199.                     assert forall|addr: int|
200.                         self@.free_frames.contains(addr)
201.                         <==> old(self)@.free_frames.contains(addr)
202.                     by {
203.                         if self@.free_frames.contains(addr) {
204.                             let i = choose|i: int|
205.                                 #[trigger] self.bitmap@.is_covered(i)
206.                                 && !self.bitmap@.set_bits.contains(i)
207.                                 && addr == frame_addr_of(i);
208.                             assert(old(self).bitmap@.is_covered(i));
209.                             assert(!old(self).bitmap@.set_bits.contains(i));
210.                         }
211.                         if old(self)@.free_frames.contains(addr) {
212.                             let i = choose|i: int|
213.                                 #[trigger] old(self).bitmap@.is_covered(i)
214.                                 && !old(self).bitmap@.set_bits.contains(i)
215.                                 && addr == frame_addr_of(i);
216.                             assert(self.bitmap@.is_covered(i));
217.                             assert(!self.bitmap@.set_bits.contains(i));
218.                         }
219.                     }
220.                     assert(self@.allocated_frames =~= old(self)@.allocated_frames);
221.                     assert(self@.free_frames =~= old(self)@.free_frames);
222. 
223.                     // old(self)@.free_frames.is_empty()
224.                     // bitmap.is_full() means all covered bits are set
225.                     assert forall|addr: int| !old(self)@.free_frames.contains(addr) by {
226.                         if old(self)@.free_frames.contains(addr) {
227.                             let i = choose|i: int|
228.                                 #[trigger] old(self).bitmap@.is_covered(i)
229.                                 && !old(self).bitmap@.set_bits.contains(i)
230.                                 && addr == frame_addr_of(i);
231.                             // is_full means all covered bits are set
232.                             assert(old(self).bitmap@.is_bit_set(i));
233.                             // contradiction with !set_bits.contains(i)
234.                         }
235.                     }
236. 
237.                     // self.inv()
238.                     self.lemma_internal_inv_preserved(old(self));
239.                     self.lemma_inv_implies_wf();
240.                 }
241.                 #[cfg(not(verus_keep_ghost))]
242.                 error!("{error:?}");
243.                 return Err(error);
